package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaKnDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("ಕೋಳಿ ಅಥವಾ ಕತ್ತೆ ಕೇಳುವುದು", "ಓ ಅಲ್ಲಾಹ್ವೇ, ನಾನು ನಿನ್ನ ಅನುಗ್ರಹವನ್ನು (ಕೋಳಿ) ಕೇಳುತ್ತೇನೆ.-ನಾನು ಶಾಪಗ್ರಸ್ತನಾದ (ಕತ್ತೆ) ಸೈತಾನ್ನಿಂದ ಅಲ್ಲಾಹನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಕೋಳಿ ಅಲ್ಲಾಹನ ಅನುಗ್ರಹವನ್ನು ಕೇಳುವುದನ್ನು ಕೇಳಿದ ಮೇಲೆ; ಕತ್ತೆ ಕಪ್ಪೆ ಕೇಳಿದಾಗ ಸೈತಾನ್ನಿಂದ ಆಶ್ರಯ ಪಡೆಯಿರಿ.", "ಕೋಳಿ ದೇವದೂತನನ್ನು ನೋಡುತ್ತದೆ ಮತ್ತು ಕತ್ತೆ ದೆವ್ವವನ್ನು ನೋಡುತ್ತದೆ."),
        "dua_something_liked" to DuaText("ಪ್ರಶಂಸನೀಯವಾದದ್ದನ್ನು ನೋಡುವುದು (ದುಷ್ಟ ಕಣ್ಣಿನ ವಿರುದ್ಧ)", "ಅಲ್ಲಾಹನು ಏನು ಬಯಸಿದ್ದನೋ ಅದನ್ನು ಆಶೀರ್ವದಿಸಿರಿ.", "ಯಾರಿಗಾದರೂ ಸೇರಿದ ಪ್ರಶಂಸನೀಯವಾದದ್ದನ್ನು ನೋಡಿದ ನಂತರ, ಆಶೀರ್ವಾದಕ್ಕಾಗಿ ಪ್ರಾರ್ಥಿಸಿ.", "ಆಶೀರ್ವಾದಕ್ಕಾಗಿ ಪ್ರಾರ್ಥಿಸುವುದರಿಂದ ದುಷ್ಟ ಕಣ್ಣುಗಳು ತಪ್ಪುತ್ತವೆ."),
        "dua_sell_buy_debt_repaid" to DuaText("ಸಾಲವನ್ನು ಮರುಪಾವತಿಸುವಾಗ", "ಅಲ್ಲಾಹ್ ನಿಮ್ಮ ಕುಟುಂಬದಲ್ಲಿ ಮತ್ತು ನಿಮ್ಮ ಸಂಪತ್ತಿನಲ್ಲಿ ನಿಮ್ಮನ್ನು ಆಶೀರ್ವದಿಸಲಿ.", "ಸಾಲವನ್ನು ಮರುಪಾವತಿಸುವಾಗ ಸಾಲದಾತನಿಗೆ.", "ಸಾಲದ ಮರುಪಾವತಿ ಎಂದರೆ ಧನ್ಯವಾದಗಳು ಮತ್ತು ಮರುಪಾವತಿ."),
        "dua_talbiyah" to DuaText("ತಲ್ಬಿಯಾ", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ಇಲ್ಲಿದ್ದೇನೆ. ನಾನು ಇಲ್ಲಿದ್ದೇನೆ, ನಿನಗೆ ಪಾಲುದಾರನಿಲ್ಲ, ನಾನು ಇಲ್ಲಿದ್ದೇನೆ. ಖಂಡಿತವಾಗಿಯೂ ಎಲ್ಲಾ ಪ್ರಶಂಸೆಗಳು, ಆಶೀರ್ವಾದಗಳು ಮತ್ತು ಪ್ರಭುತ್ವವು ನಿನ್ನದೇ. ನಿನಗೆ ಪಾಲುದಾರನಿಲ್ಲ.", "ಇಹ್ರಾಮ್ ಪ್ರವೇಶಿಸಿದ ನಂತರ ಗಟ್ಟಿಯಾಗಿ.", "ಹಜ್ ಮತ್ತು ಉಮ್ರಾದ ಲಾಂಛನ."),
        "dua_yamani_hajar" to DuaText("ರುಕ್ನ್ ಯಮನಿ ಮತ್ತು ಹಜಾರ್ ಅಸ್ವಾದ್ ನಡುವೆ", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನಮಗೆ ಈ ಲೋಕದಲ್ಲಿ ಒಳ್ಳೆಯದನ್ನು ಮತ್ತು ಪರಲೋಕದಲ್ಲಿ ಒಳ್ಳೆಯದನ್ನು ಕರುಣಿಸು ಮತ್ತು ನರಕದ ಶಿಕ್ಷೆಯಿಂದ ನಮ್ಮನ್ನು ರಕ್ಷಿಸು.", "ತವಾಫ್ನಲ್ಲಿ, ಯೆಮೆನ್ ಮೂಲೆ ಮತ್ತು ಕಪ್ಪು ಕಲ್ಲಿನ ನಡುವೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ತವಫ್ನಲ್ಲಿರುವ ಈ ಸ್ಥಳದಲ್ಲಿ ಇದನ್ನು ಪಠಿಸಿದರು."),
        "dua_safa_marwa" to DuaText("ಸಫಾ ಮತ್ತು ಮಾರ್ವಾ ಬಗ್ಗೆ", "ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ, ಒಬ್ಬನೇ, ಪಾಲುದಾರನಿಲ್ಲದ, ಆರಾಧಿಸಲ್ಪಡುವ ಹಕ್ಕು ಯಾರಿಗೂ ಇಲ್ಲ. ಪ್ರಭುತ್ವವು ಅವನಿಗೇ ಇದೆ ಮತ್ತು ಸ್ತುತಿಯೂ ಅವನಿಗೇ ಇದೆ, ಮತ್ತು ಎಲ್ಲ ವಿಷಯಗಳ ಮೇಲೆ ಅವನಿಗೆ ಅಧಿಕಾರವಿದೆ. ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ ಆರಾಧಿಸಲ್ಪಡುವ ಹಕ್ಕು ಯಾರಿಗೂ ಇಲ್ಲ. ಅವನು ತನ್ನ ವಾಗ್ದಾನವನ್ನು ಪೂರೈಸಿದನು, ತನ್ನ ಸೇವಕನಿಗೆ ಸಹಾಯ ಮಾಡಿದನು ಮತ್ತು ಒಕ್ಕೂಟಗಳನ್ನು ಸೋಲಿಸಿದನು.", "ಸಫಾ ಏರುವುದು ಮತ್ತು ಕಿಬ್ಲಾವನ್ನು ಎದುರಿಸುವುದು (ಮೂರು ಬಾರಿ).", "ಸಫಾ ಮತ್ತು ಮಾರ್ವಾ ಕುರಿತು ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರ ದಿಕ್ರ್."),
        "dua_arafah" to DuaText("ಅರಾಫಾ ದಿನದ ಅತ್ಯುತ್ತಮ ದುವಾ", "ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ, ಒಬ್ಬನೇ, ಪಾಲುದಾರನಿಲ್ಲದೆ ಆರಾಧಿಸಲ್ಪಡುವ ಹಕ್ಕು ಯಾರಿಗೂ ಇಲ್ಲ. ಪ್ರಭುತ್ವವು ಅವನಿಗೇ ಸೇರಿದ್ದು, ಸ್ತುತಿಯೂ ಅವನಿಗೇ ಸೇರಿದ್ದು, ಅವನು ಎಲ್ಲ ವಸ್ತುಗಳ ಮೇಲೆ ಪ್ರಭುತ್ವವನ್ನು ಹೊಂದಿದ್ದಾನೆ.", "ಅರಾಫಾದ ದಿನ-ಅತ್ಯುತ್ತಮ ದುಆ.", "ಅರಾಫಾ ದಿನದ ದುಆ ಅತ್ಯುತ್ತಮ ದುಆ ಆಗಿದೆ, ಮತ್ತು ಅತ್ಯುತ್ತಮ ಪದಗಳು ಇವು."),
        "dua_takbeer_tashreeq" to DuaText("ತಕ್ಬೀರ್-ಎ-ತಶ್ರೀಕ್", "ಅಲ್ಲಾಹ್ ಶ್ರೇಷ್ಠನು, ಅಲ್ಲಾಹ್ ಶ್ರೇಷ್ಠನು. ಅಲ್ಲಾಹನ ಹೊರತು ಬೇರೆ ದೇವರುಗಳಿಲ್ಲ. ಅಲ್ಲಾಹ್ ಶ್ರೇಷ್ಠನು, ಅಲ್ಲಾಹ್ ಶ್ರೇಷ್ಠನು, ಮತ್ತು ಎಲ್ಲಾ ಸ್ತುತಿಯೂ ಅಲ್ಲಾಹನಿಗೇ ಸಲ್ಲುತ್ತದೆ.", "9ನೇ ಧುಲ್-ಹಿಜ್ಜಾದ ಫಜ್ರಿನಿಂದ 13ನೇ ಧುಲ್-ಹಿಜ್ಜಾದ ಅಸ್ರಿಗೆ ಪ್ರತಿಯೊಂದು ಕಡ್ಡಾಯ ಪ್ರಾರ್ಥನೆಯ ನಂತರ.", "ಅಲಿ ಮತ್ತು ಇಬ್ನ್ ಮಸೂದ್ (ರಾ) ಅವರಿಂದ ವರದಿಯಾಗಿದೆ-ಹನಾಫಿಗಳ ಪ್ರಕಾರ ವಾಜಿಬ್."),
        "dua_zamzam" to DuaText("ಝಮ್ಜಮ್ ಕುಡಿಯುವುದು", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನಗೆ ಪ್ರಯೋಜನಕಾರಿ ಜ್ಞಾನ, ಸಮೃದ್ಧವಾದ ಆಹಾರ ಮತ್ತು ಪ್ರತಿಯೊಂದು ರೋಗದಿಂದ ಗುಣಪಡಿಸುವ ಗುಣವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಝಮ್ಜಾಮ್ ಕುಡಿಯುವಾಗ, ನೀವು ಏನನ್ನು ಬಯಸುತ್ತೀರೋ ಅದಕ್ಕೆ ದುವಾ ಮಾಡಿ.", "ಝಮ್ಜಮ್ ಎಂದರೆ ಅದು ಯಾವುದಕ್ಕೆ ಕುಡಿಯುತ್ತದೆಯೋ ಅದಕ್ಕೆ (ಇಬ್ನ್ ಮಜಾಹ್ 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("ಸೃಷ್ಟಿಯ ಬಗ್ಗೆ ಪ್ರತಿಬಿಂಬಿಸುವುದು", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನೀನು ಇದೆಲ್ಲವನ್ನೂ ವ್ಯರ್ಥವಾಗಿ ಸೃಷ್ಟಿಸಲಿಲ್ಲ. ನೀನು ಮಹಿಮೆಯುಳ್ಳವನಾಗಿದ್ದೀ. ಆದ್ದರಿಂದ ನಮ್ಮನ್ನು ನರಕದ ಶಿಕ್ಷೆಯಿಂದ ರಕ್ಷಿಸು.", "ಆಕಾಶ ಮತ್ತು ಭೂಮಿಯ ಸೃಷ್ಟಿಯ ಬಗ್ಗೆ ಯೋಚಿಸುವವರ ದುಆ.", "ತಿಳುವಳಿಕೆಯುಳ್ಳ ಜನರ ದುಆ (ಉಲುಲ್-ಅಲ್ಬಾಬ್)."),
        "dua_q_sami_na_munadiyan" to DuaText("ನಂಬಿಕೆಗೆ ಕರೆದವನ ಮಾತನ್ನು ನಾವು ಕೇಳಿದ್ದೇವೆ", "ನಮ್ಮ ಒಡೆಯನೇ, ಒಬ್ಬ ಕರೆ ಮಾಡುವವನು \"ನಿನ್ನ ಒಡೆಯನನ್ನು ನಂಬಿಸು\" ಎಂದು ಕರೆದದ್ದನ್ನು ನಾವು ಕೇಳಿದ್ದೇವೆ. ನಾವು ನಂಬಿದೆವು. ನಮ್ಮ ಒಡೆಯನೇ, ನಮ್ಮ ಪಾಪಗಳನ್ನು ಕ್ಷಮಿಸು. ನಮ್ಮ ದುಷ್ಕೃತ್ಯಗಳನ್ನು ನಮ್ಮಿಂದ ತೆಗೆದುಹಾಕಿಸು. ಮತ್ತು ಸದ್ಗುಣಶೀಲರೊಂದಿಗೆ ನಮ್ಮನ್ನು ಸಾಯಿಸು.", "ನಂಬಿಕೆಗೆ ಮತ್ತು ನೀತಿವಂತರ ನಡುವೆ ಸಾಯುವ ಒಂದು ದುಆ.", "ಕ್ಷಮೆಯಾಚಿಸುವ ಮತ್ತು ಒಳ್ಳೆಯ ಅಂತ್ಯದ ಒಂದು ದುಆ."),
        "dua_q_atina_ma_waadtana" to DuaText("ನೀವು ವಾಗ್ದಾನ ಮಾಡಿದ್ದನ್ನು ನಮಗೆ ನೀಡಿ.", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನಿನ್ನ ದೂತರ ಮೂಲಕ ನಮಗೆ ನೀನೇನು ವಾಗ್ದಾನ ಮಾಡಿದ್ದೀಯೋ ಅದನ್ನು ನಮಗೆ ದಯಪಾಲಿಸು. ಮತ್ತು ಪುನರುತ್ಥಾನದ ದಿನದಂದು ನಮಗೆ ಅವಮಾನ ಮಾಡಬೇಡ. ಖಂಡಿತ ನೀನು ನಿನ್ನ ವಾಗ್ದಾನವನ್ನು ಮುರಿಯುವುದಿಲ್ಲ.", "ಪುನರುತ್ಥಾನದ ದಿನದಂದು ಅವಮಾನದಿಂದ ನಿರಾಶ್ರಿತರಾಗಿರಿ.", "ಪರಕಾಲದಲ್ಲಿ ಗೌರವವನ್ನು ಹುಡುಕುವುದು."),
        "dua_q_israfana" to DuaText("ನಮ್ಮ ಮಿತಿಮೀರಿದ ಕ್ರಿಯೆಗಳನ್ನು ಕ್ಷಮಿಸಿ.", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನಮ್ಮ ಪಾಪಗಳನ್ನು ಮತ್ತು ನಮ್ಮ ವ್ಯವಹಾರಗಳಲ್ಲಿ ನಮ್ಮ ಮಿತಿಮೀರಿದ ಕೃತ್ಯಗಳನ್ನು ನಮಗೆ ಕ್ಷಮಿಸು, ನಮ್ಮ ಪಾದಗಳನ್ನು ದೃಢಗೊಳಿಸಿ ಮತ್ತು ಅವಿಶ್ವಾಸಿಗಳ ವಿರುದ್ಧ ನಮಗೆ ಸಹಾಯ ಮಾಡು.", "ಹಿಂದಿನ ಪ್ರವಾದಿಗಳ ಸಹಚರರ ದುಆ.", "ಸ್ಥಿರತೆ ಮತ್ತು ಕ್ಷಮೆಗಾಗಿ ಒಂದು ದುಆ."),
        "dua_q_jamiun_nas" to DuaText("ನೀವು ಮಾನವಕುಲವನ್ನು ಒಟ್ಟುಗೂಡಿಸುತ್ತೀರಿ", "ನಮ್ಮ ಒಡೆಯನೇ, ಯಾವ ದಿನದ ಬಗ್ಗೆ ಯಾವುದೇ ಸಂದೇಹವಿಲ್ಲವೋ ಆ ದಿನದಂದು ನೀನು ಮನುಷ್ಯರನ್ನು ಒಟ್ಟುಗೂಡಿಸುವೆ. ಖಂಡಿತವಾಗಿಯೂ ಅಲ್ಲಾಹ್ ತನ್ನ ವಾಗ್ದಾನವನ್ನು ಮುರಿಯುವುದಿಲ್ಲ.", "ಪುನರುತ್ಥಾನದ ದಿನದಂದು ಖಚಿತತೆಯನ್ನು ದೃಢೀಕರಿಸುವುದು.", "ಜ್ಞಾನದಲ್ಲಿ ದೃಢವಾಗಿ ನೆಲೆಗೊಂಡಿರುವವರ ದುಆ."),
        "dua_q_maash_shahidin" to DuaText("ಸಾಕ್ಷಿಗಳ ನಡುವೆ ನಮಗೆ ಬರೆಯಿರಿ", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನಾವು ನಂಬಿಕೆಯಿಟ್ಟಿದ್ದೇವೆ, ಆದ್ದರಿಂದ ಸಾಕ್ಷಿದಾರರ ನಡುವೆ ನಮ್ಮನ್ನು ಬರೆಯಿರಿ.", "ಸತ್ಯವನ್ನು ಗುರುತಿಸಿದ ಮತ್ತು ನಂಬಿದವರ ದುಆ.", "ಒಬ್ಬರ ನಂಬಿಕೆಯನ್ನು ಸ್ವೀಕರಿಸಲು ಒಂದು ದುಆ."),
        "dua_q_la_tajalna_zalimin" to DuaText("ತಪ್ಪು ಮಾಡುವವರೊಂದಿಗೆ ಅಲ್ಲ", "ನಮ್ಮ ಒಡೆಯನೇ, ನಮ್ಮನ್ನು ದುಷ್ಕರ್ಮಿಗಳ ಜೊತೆಗೂಡಿಸಬೇಡ.", "ಅಲ್-ಅರಾಫ್ ಜನರ ದುಆ.", "ತಪ್ಪಿತಸ್ಥರ ಭವಿಷ್ಯದಿಂದ ನಿರಾಶ್ರಿತರಾಗಿರಿ."),
        "dua_q_tawaffana_muslimin" to DuaText("ಮುಸ್ಲಿಮರಾಗಿ ತಾಳ್ಮೆ ಮತ್ತು ಸಾವು", "ನಮ್ಮ ಒಡೆಯನೇ, ನಮ್ಮ ಮೇಲೆ ತಾಳ್ಮೆಯನ್ನು ಸುರಿಸು ಮತ್ತು ಮುಸ್ಲಿಮರಾಗಿ ನಮ್ಮನ್ನು ಸಾಯುವಂತೆ ಮಾಡು.", "ಫರೋಹನ ಮಾಂತ್ರಿಕರು ನಂಬಿದಾಗ ಅವರ ದುಆ.", "ಪರೀಕ್ಷೆಯಲ್ಲಿ ತಾಳ್ಮೆ ಮತ್ತು ನಂಬಿಕೆಯ ಮೇಲೆ ಅಂತ್ಯ."),
        "dua_q_la_tajalna_fitnah" to DuaText("ದಬ್ಬಾಳಿಕೆಯವರಿಗೆ ಇದು ವಿಚಾರಣೆಯಲ್ಲ", "ನಾವು ಅಲ್ಲಾಹನ ಮೇಲೆ ಅವಲಂಬಿತರಾಗಿದ್ದೇವೆ. ನಮ್ಮ ಒಡೆಯನೇ, ನೀನು ನಮಗೆ ಅನ್ಯಾಯ ಮಾಡಿದ ಜನರ ಮೇಲೆ ಪರೀಕ್ಷೆಯನ್ನು ಮಾಡಬೇಡ. ಮತ್ತು ನಿನ್ನ ಕರುಣೆಯಿಂದ ನಮ್ಮನ್ನು ಆ ಕಾಫೇರ ಜನರಿಂದ ರಕ್ಷಿಸು.", "ಮೂಸಾ (ಎ. ಎಸ್) ಜನರ ದುಆ.", "ದಬ್ಬಾಳಿಕೆ ಮತ್ತು ದಬ್ಬಾಳಿಕೆಯಿಂದ ರಕ್ಷಿಸಲು ಒಂದು ದುಆ."),
        "dua_q_nuh_ma_laysa_li" to DuaText("ಕ್ಷಮೆಗಾಗಿ ನೂಹ್ (ಅ. ಸ.) ನ ದುವಾ", "ನನ್ನ ಒಡೆಯನೇ, ನನಗೆ ತಿಳಿಯದ ವಿಷಯಕ್ಕಾಗಿ ನಿನ್ನನ್ನು ಬೇಡಿಕೊಳ್ಳುವುದರಿಂದ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ. ಮತ್ತು ನೀನು ನನ್ನನ್ನು ಕ್ಷಮಿಸಿ ನನ್ನ ಮೇಲೆ ಕರುಣೆ ತೋರಿಸದ ಹೊರತು ನಾನು ನಷ್ಟಕ್ಕೊಳಗಾದವರಲ್ಲಿ ಒಬ್ಬನಾಗುವೆನು.", "ಪ್ರವಾದಿ ನೂಹ್ (ಅ. ಸ.) ಅವರ ಪಶ್ಚಾತ್ತಾಪದ ದುಆ.", "ಸರಿಯಾದ ನಡವಳಿಕೆಯಿಂದ ಕೇಳುವ ಪಾಠ."),
        "dua_q_mudkhala_sidq" to DuaText("ಸತ್ಯದ ಪ್ರವೇಶ ಮತ್ತು ನಿರ್ಗಮನ", "ನನ್ನ ಒಡೆಯನೇ, ನಾನು ಸತ್ಯದೊಂದಿಗೆ ಪ್ರವೇಶಿಸುವಂತೆ ಮತ್ತು ಸತ್ಯದೊಂದಿಗೆ ನಿರ್ಗಮಿಸುವಂತೆ ಮಾಡು, ಮತ್ತು ನನಗೆ ನಿನ್ನದೇ ಆದ ಸಹಾಯಕ ಅಧಿಕಾರವನ್ನು ಕೊಡು.", "ಹೊಸ ಕೆಲಸಕ್ಕೆ ಪ್ರವೇಶಿಸುವ ಮೊದಲು, ಮನೆ ಅಥವಾ ಸ್ಥಳ.", "ಹಿಜ್ರಾದ ಸಮಯದಲ್ಲಿ ದುಆ ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರಿಗೆ ಕಲಿಸಿತು."),
        "dua_q_la_tadharni_fardan" to DuaText("ಜಕಾರಿಯಾದ ದುವಾ (ಎ. ಎಸ್)-ನನ್ನನ್ನು ಏಕಾಂಗಿಯಾಗಿ ಬಿಡಬೇಡಿ", "ನನ್ನ ಒಡೆಯನೇ, ನನ್ನನ್ನು ಏಕಾಂಗಿಯಾಗಿ ಬಿಡಬೇಡ, ಆಗ ನೀನು ಅತ್ಯುತ್ತಮ ಉತ್ತರಾಧಿಕಾರಿ.", "ಮಕ್ಕಳನ್ನು ಹುಡುಕುವವರಿಗಾಗಿ.", "ಈ ದುಆ ಮೂಲಕ ಅಲ್ಲಾಹ್ ಯಾಹ್ಯಾ (ಎ. ಎಸ್) ಅನ್ನು ನೀಡಿದನು."),
        "dua_q_munzalan_mubarakan" to DuaText("ಒಂದು ಪೂಜ್ಯವಾದ ಇಳಿಯುವ ಸ್ಥಳ", "ನನ್ನ ಒಡೆಯನೇ, ನಾನು ಒಂದು ಪುಣ್ಯಪೂರ್ಣವಾದ ಇಳಿಯುವ ಸ್ಥಳದಲ್ಲಿ ಇಳಿಯಲಿ, ಮತ್ತು ಭೂಮಿಯನ್ನು ತರುವವರಲ್ಲಿ ನೀನು ಅತ್ಯುತ್ತಮನಾಗಿದ್ದೀ.", "ಹೊಸ ಮನೆಗೆ ಸ್ಥಳಾಂತರಗೊಳ್ಳುವಾಗ ಅಥವಾ ಎಲ್ಲೋ ನಿಲ್ಲುವಾಗ-ನೂಹ್ (ಎ. ಎಸ್) ನ ದುಆ.", "ಹೊಸ ಸ್ಥಳದಲ್ಲಿ ಆಶೀರ್ವಾದಕ್ಕಾಗಿ ಒಂದು ದುಆ."),
        "dua_q_amanna_faghfir" to DuaText("ನಾವು ನಂಬುತ್ತೇವೆ, ಆದ್ದರಿಂದ ನಮ್ಮನ್ನು ಕ್ಷಮಿಸಿ.", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನಾವು ನಂಬಿಕೆಯಿಟ್ಟಿದ್ದೇವೆ. ಆದ್ದರಿಂದ ನಮ್ಮನ್ನು ಕ್ಷಮಿಸು ಮತ್ತು ನಮ್ಮ ಮೇಲೆ ಕರುಣೆ ತೋರಿಸು. ಮತ್ತು ನೀನು ಕರುಣೆಯುಳ್ಳವರಲ್ಲಿ ಅತ್ಯುತ್ತಮನಾಗಿದ್ದೀ.", "ಅಲ್ಲಾಹುವಿನ ನೀತಿವಂತ ಸೇವಕರ ದುಆ.", "ಕ್ಷಮೆ ಮತ್ತು ಕರುಣೆಗಾಗಿ ಸಮಗ್ರ ದುಆ."),
        "dua_q_isrif_jahannam" to DuaText("ನರಕದ ಶಿಕ್ಷೆಯನ್ನು ತಪ್ಪಿಸಿ", "ನಮ್ಮ ಒಡೆಯನೇ, ನರಕದ ಶಿಕ್ಷೆಯನ್ನು ನಮ್ಮಿಂದ ತಪ್ಪಿಸು. ಖಂಡಿತವಾಗಿಯೂ ಅದರ ಶಿಕ್ಷೆಯು ನಿರಂತರವಾದದ್ದು. ಖಂಡಿತವಾಗಿಯೂ ಇದು ಕೆಟ್ಟ ನೆಲೆ ಮತ್ತು ವಾಸಸ್ಥಾನವಾಗಿದೆ.", "ಪರಮ ಕರುಣಾಮಯನ ಸೇವಕರ ದುಆ ('ಇಬ್ದ್ ಅರ್-ರೆಹಮಾನ್).", "ನರಕದಿಂದ ಆಶ್ರಯಕ್ಕಾಗಿ ಕುರಾನ್ ದುಆ."),
        "dua_q_hab_li_hukman" to DuaText("ಇಬ್ರಾಹಿಂನ ದುವಾ (ಎ. ಎಸ್)-ಬುದ್ಧಿವಂತಿಕೆ ಮತ್ತು ಜನ್ನಾಹ್", "ನನ್ನ ಒಡೆಯನೇ, ನನಗೆ ಬುದ್ಧಿವಂತಿಕೆಯನ್ನು ನೀಡಿ ಮತ್ತು ನೀತಿವಂತರೊಂದಿಗೆ ನನ್ನೊಂದಿಗೆ ಸೇರಿ, ನಂತರದ ಪೀಳಿಗೆಗಳಲ್ಲಿ ನನಗೆ ಗೌರವಾನ್ವಿತ ಉಲ್ಲೇಖವನ್ನು ನೀಡಿ, ಮತ್ತು ನನ್ನನ್ನು ಆನಂದದ ಉದ್ಯಾನದ ಉತ್ತರಾಧಿಕಾರಿಗಳಲ್ಲಿ ಒಬ್ಬನನ್ನಾಗಿ ಮಾಡಿ.", "ವಿವೇಕವನ್ನು ಕೇಳುವುದು, ನೀತಿವಂತರು ಮತ್ತು ಸ್ವರ್ಗದ ಸಂಗಾತಿ.", "ಇಬ್ರಾಹಿಂ (ಅ. ಸ.) ಅವರ ಸಮಗ್ರ ದುಆ."),
        "dua_q_lut_najjini_ahli" to DuaText("ಲುತ್ (ಎ. ಎಸ್) ನ ದುವಾ-ನನ್ನ ಕುಟುಂಬವನ್ನು ಉಳಿಸಿ", "ನನ್ನ ಒಡೆಯನೇ, ನನ್ನನ್ನು ಮತ್ತು ನನ್ನ ಕುಟುಂಬವನ್ನು ಅವರು ಮಾಡುತ್ತಿರುವ (ಅದರ) ಪರಿಣಾಮದಿಂದ ರಕ್ಷಿಸು.", "ಕೆಟ್ಟ ವಾತಾವರಣದಿಂದ ಒಬ್ಬರ ಕುಟುಂಬವನ್ನು ರಕ್ಷಿಸುವುದು.", "ಕುಟುಂಬವನ್ನು ದುಷ್ಟತನದಿಂದ ರಕ್ಷಿಸುವುದು."),
        "dua_q_sulaiman_awzini" to DuaText("ಕೃತಜ್ಞತೆಗಾಗಿ ಸುಲೇಮಾನ್ (ಎ. ಎಸ್) ನ ದುವಾ", "ನನ್ನ ಒಡೆಯನೇ, ನೀನು ನನಗೆ ಮತ್ತು ನನ್ನ ಹೆತ್ತವರಿಗೆ ನೀಡಿದ ಉಪಕಾರಕ್ಕಾಗಿ ನಾನು ಕೃತಜ್ಞನಾಗಿರಲು ಮತ್ತು ನಿನಗೆ ಇಷ್ಟವಾದ ಒಳ್ಳೆಯ ಕಾರ್ಯಗಳನ್ನು ಮಾಡಲು ಮತ್ತು ನಿನ್ನ ಕರುಣೆಯಿಂದ ನನ್ನನ್ನು ನಿನ್ನ ನೀತಿವಂತ ಸೇವಕರಲ್ಲಿ ಸೇರಿಸಿಕೊಳ್ಳಲು ನನಗೆ ಅವಕಾಶ ಮಾಡಿಕೊಡು.", "ಆಶೀರ್ವಾದಗಳಿಗೆ ಕೃತಜ್ಞರಾಗಿರುವ ಸಾಮರ್ಥ್ಯಕ್ಕಾಗಿ.", "ಸುಲೇಮಾನ್ (ಎ. ಎಸ್) ಅವರ ಕೃತಜ್ಞತೆಯ ದುಆ."),
        "dua_q_musa_zalamtu" to DuaText("ಮೂಸಾ (ಅ. ಸ.) ರ ದುವಾ-ನಾನು ನನ್ನಷ್ಟಕ್ಕೇ ಅನ್ಯಾಯ ಮಾಡಿಕೊಂಡಿದ್ದೇನೆ.", "ನನ್ನ ಒಡೆಯನೇ, ನಾನು ನನ್ನ ಮೇಲೆ ಅನ್ಯಾಯ ಮಾಡಿದ್ದೇನೆ, ಆದ್ದರಿಂದ ನನ್ನನ್ನು ಕ್ಷಮಿಸು.", "ತಪ್ಪಿನ ನಂತರ ತಕ್ಷಣದ ಪಶ್ಚಾತ್ತಾಪ.", "ಅಲ್ಲಾಹನು ಮೂಸ (ಅ. ಸ.) ನನ್ನು ಕ್ಷಮಿಸಿದನು."),
        "dua_q_musa_najjini" to DuaText("ಮೂಸಾ (ಅ. ಸ.) ರ ದುವಾ-ನನ್ನನ್ನು ದಬ್ಬಾಳಿಕೆಯಿಂದ ರಕ್ಷಿಸು", "ನನ್ನ ಒಡೆಯನೇ, ಅನ್ಯಾಯ ಮಾಡುವ ಜನರಿಂದ ನನ್ನನ್ನು ರಕ್ಷಿಸು.", "ದಬ್ಬಾಳಿಕೆಯವರಿಗೆ ಹೆದರುತ್ತಿದ್ದಾಗ.", "ಈಜಿಪ್ಟ್ನಿಂದ ಹೊರಡುವಾಗ ಮೂಸಾದ (ಎ. ಎಸ್) ದುಆ."),
        "dua_q_lut_unsurni" to DuaText("ಲೂತ್ (ಎ. ಎಸ್) ನ ದುವಾ-ಭ್ರಷ್ಟರ ವಿರುದ್ಧ ಸಹಾಯ", "ನನ್ನ ಒಡೆಯನೇ, ಭ್ರಷ್ಟ ಜನರ ವಿರುದ್ಧ ನನಗೆ ಸಹಾಯ ಮಾಡು.", "ಭ್ರಷ್ಟಾಚಾರವನ್ನು ಹರಡುವವರ ವಿರುದ್ಧ ಸಹಾಯಕ್ಕಾಗಿ.", "ಸತ್ಯದ ಮೇಲೆ ದೃಢವಾಗಿ ನಿಲ್ಲುವವರ ದ್ವಂದ್ವ."),
        "dua_q_hab_li_salihin" to DuaText("ನೀತಿವಂತ ಮಗುವಿಗಾಗಿ ಇಬ್ರಾಹಿಂನ (ಎ. ಎಸ್) ದುವಾ", "ನನ್ನ ಒಡೆಯನೇ, ನನಗೆ ಸದ್ಗುಣಶೀಲರಲ್ಲಿ ಒಬ್ಬ ಮಗುವನ್ನು ಕರುಣಿಸು.", "ನೀತಿವಂತ ಮಕ್ಕಳನ್ನು ಕೇಳುವುದು.", "ಈ ಮೂಲಕ ದುಆ ಇಸ್ಮಾಯಿಲ್ (ಎ. ಎಸ್) ಅನ್ನು ನೀಡಲಾಯಿತು."),
        "dua_q_wasita_kulla_shay" to DuaText("ಸಿಂಹಾಸನವನ್ನು ಹೊತ್ತಿರುವ ದೇವತೆಗಳ ದುವಾ", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನೀನು ಎಲ್ಲಾ ವಿಷಯಗಳನ್ನು ಕರುಣೆ ಮತ್ತು ಜ್ಞಾನದಿಂದ ಆವರಿಸಿಕೊಂಡಿದ್ದೀ. ಆದ್ದರಿಂದ ಪಶ್ಚಾತ್ತಾಪಪಟ್ಟು ನಿನ್ನ ಮಾರ್ಗವನ್ನು ಅನುಸರಿಸುವವರನ್ನು ಕ್ಷಮಿಸು ಮತ್ತು ಅವರನ್ನು ನರಕದ ಶಿಕ್ಷೆಯಿಂದ ರಕ್ಷಿಸು.", "ಸಿಂಹಾಸನವನ್ನು ಹೊತ್ತಿರುವ ದೇವತೆಗಳು ಭಕ್ತರಿಗಾಗಿ ಈ ದುಆವನ್ನು ಮಾಡುತ್ತಾರೆ.", "ದೇವತೆಗಳ ದುಆದಲ್ಲಿ ಸೇರಿಸಿಕೊಳ್ಳುವ ಉದ್ದೇಶದಿಂದ ಪಠಿಸಲಾಯಿತು."),
        "dua_q_ikhwanina" to DuaText("ನಮಗೆ ಮೊದಲು ಇದ್ದ ನಮ್ಮ ಸಹೋದರರಿಗಾಗಿ", "ನಮ್ಮ ಒಡೆಯನೇ, ನಮಗೆ ಮತ್ತು ನಮಗೆ ಮೊದಲು ನಂಬಿಕೆಯಿಟ್ಟಿದ್ದ ನಮ್ಮ ಸಹೋದರರಿಗೆ ಕ್ಷಮಿಸು. ಮತ್ತು ನಂಬಿಕೆಯುಳ್ಳವರ ಬಗ್ಗೆ ನಮ್ಮ ಹೃದಯದಲ್ಲಿ ಅಸಮಾಧಾನವನ್ನು ಮೂಡಿಸಬೇಡ. ನಮ್ಮ ಒಡೆಯನೇ, ನೀನು ಖಂಡಿತವಾಗಿಯೂ ಕರುಣಾಮಯಿ, ಕರುಣಾಮಯಿ.", "ಮೊದಲು ಬಂದ ಭಕ್ತರಿಗೆ ಮತ್ತು ಶುದ್ಧ ಹೃದಯಕ್ಕಾಗಿ ಒಂದು ದುಆ.", "ಉದಾತ್ತ ಸಹಚರರು (ಆರ್. ಎ.) ಮತ್ತು ಹಿಂದಿನ ಭಕ್ತರಿಗೆ ಒಂದು ದುಆ."),
        "dua_q_alayka_tawakkalna" to DuaText("ನಾವು ನಿನ್ನ ಮೇಲೆ ಅವಲಂಬಿತರಾಗಿದ್ದೇವೆ (ಇಬ್ರಾಹಿಮ್ ಅ. ಸ.)", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನಾವು ನಿನ್ನ ಮೇಲೆ ಅವಲಂಬಿತರಾಗಿದ್ದೇವೆ. ನಾವು ನಿನ್ನ ಕಡೆಗೆ ತಿರುಗುತ್ತೇವೆ ಮತ್ತು ನಿನ್ನ ಕಡೆಗೆ ಹಿಂದಿರುಗುತ್ತೇವೆ. ನಮ್ಮ ಒಡೆಯನೇ, ನಮ್ಮನ್ನು ಕಾಡುವವರಿಗೆ ಪರೀಕ್ಷೆಯನ್ನಾಗಿ ಮಾಡಬೇಡ. ಮತ್ತು ನಮ್ಮನ್ನು ಕ್ಷಮಿಸು. ನಮ್ಮ ಒಡೆಯನೇ, ನೀನು ಖಂಡಿತವಾಗಿಯೂ ಸರ್ವಶಕ್ತನೂ, ತತ್ವಜ್ಞನೂ ಆಗಿದ್ದೀ.", "ಇಬ್ರಾಹಿಂ (ಅ. ಸ.) ಮತ್ತು ಅವನ ಸಹಚರರ ದುಆ.", "ಅಲ್ಲಾಹನನ್ನು ಅವಲಂಬಿಸುವ ಮತ್ತು ಆತನ ಕಡೆಗೆ ತಿರುಗುವ ಒಂದು ದ್ವಂದ್ವ."),
        "dua_q_atmim_nurana" to DuaText("ನಮ್ಮ ಬೆಳಕನ್ನು ಪರಿಪೂರ್ಣಗೊಳಿಸಿ", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನಮ್ಮ ಬೆಳಕನ್ನು ನಮಗೆ ಪರಿಪೂರ್ಣಗೊಳಿಸಿ. ಮತ್ತು ನಮ್ಮನ್ನು ಕ್ಷಮಿಸು. ನಿಶ್ಚಯವಾಗಿ ನೀನು ಎಲ್ಲದರ ಮೇಲೆ ಪ್ರಭುತ್ವವುಳ್ಳವನಾಗಿದ್ದೀ.", "ಪುನರುತ್ಥಾನದ ದಿನದಂದು ವಿಶ್ವಾಸಿಗಳ ದುಆ.", "ಸಿರತ್ನಲ್ಲಿ ಬೆಳಕು ಕೇಳುವುದು."),
        "dua_q_asiya_baytan" to DuaText("ಏಷ್ಯಾದ ದುವಾ-ಜನ್ನಾದ ಒಂದು ಮನೆ", "ನನ್ನ ಒಡೆಯನೇ, ನಿನಗೆ ಹತ್ತಿರದಲ್ಲಿ ಸ್ವರ್ಗದಲ್ಲಿ ಒಂದು ಮನೆಯನ್ನು ಕಟ್ಟಿಸು. ಫರೋಹನ ಮತ್ತು ಅವನ ಕರ್ಮಗಳಿಂದ ನನ್ನನ್ನು ರಕ್ಷಿಸು. ಮತ್ತು ದುಷ್ಕರ್ಮಿಗಳಿಂದ ನನ್ನನ್ನು ರಕ್ಷಿಸು.", "ಫೇರೋನ ಹೆಂಡತಿಯಾದ ಆಸಿಯಳ ದೂವಾ.", "ಅಲ್ಲಾಹು ಆಕೆಯನ್ನು ಭಕ್ತರಿಗೆ ಮಾದರಿಯನ್ನಾಗಿ ಮಾಡಿದನು."),
        "dua_adhan_response" to DuaText("ಅಧಾನಕ್ಕೆ ಪ್ರತಿಕ್ರಿಯೆ", "ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ ಬೇರೆ ಯಾವುದೇ ಶಕ್ತಿ ಮತ್ತು ಶಕ್ತಿ ಇಲ್ಲ.", "'ಹಯ್ಯಾ'ಅಲಾಸ್-ಸಲಾಹ್'ಮತ್ತು'ಹಯ್ಯಾ'ಅಲಾಲ್-ಫಲಾಹ್'ನಲ್ಲಿ ಮುಯೆಝಿನ್ ಏನು ಹೇಳುತ್ತಾರೋ ಅದನ್ನು ಪುನರಾವರ್ತಿಸಿ.", "ಹೃದಯದಿಂದ ಪ್ರತಿಕ್ರಿಯಿಸುವವರು ಸ್ವರ್ಗವನ್ನು ಪ್ರವೇಶಿಸುತ್ತಾರೆ."),
        "dua_adhan_shahadah" to DuaText("ಮುಅಜ್ಜೀನರ ಶಹಾದಾದ ನಂತರ", "ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ, ಒಬ್ಬನೇ, ಪಾಲುದಾರನಿಲ್ಲದೆ, ಪೂಜಿಸಲ್ಪಡುವ ಹಕ್ಕು ಯಾರಿಗೂ ಇಲ್ಲ ಮತ್ತು ಮುಹಮ್ಮದ್ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಆತನ ಸೇವಕ ಮತ್ತು ಸಂದೇಶವಾಹಕರಾಗಿದ್ದಾರೆ ಎಂಬುದಕ್ಕೆ ನಾನೂ ಸಾಕ್ಷಿಯಾಗಿದ್ದೇನೆ. ಅಲ್ಲಾಹನು ನನಗೆ ಒಡೆಯನಾಗಿದ್ದರೆ, ಮುಹಮ್ಮದ್ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರಿಗೆ ಸಂದೇಶವಾಹಕರಾಗಿದ್ದರೆ ಮತ್ತು ಇಸ್ಲಾಂ ಧರ್ಮಕ್ಕೆ ಧರ್ಮವಾಗಿದ್ದರೆ ನನಗೆ ಸಂತೋಷವಾಗುತ್ತದೆ.", "ಮುಯೆಝಿನ್ನ ನಂಬಿಕೆಯ ಸಾಕ್ಷ್ಯವನ್ನು ಕೇಳಿದ ನಂತರ.", "ಆತನ ಪಾಪಗಳು ಕ್ಷಮಿಸಲ್ಪಡುತ್ತವೆ."),
        "dua_istiftah_baid" to DuaText("ದುವಾ ತೆರೆಯುವುದುಃ ನನ್ನನ್ನು ಪಾಪಗಳಿಂದ ದೂರವಿಡಿ", "ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ಪೂರ್ವವನ್ನು ಪಶ್ಚಿಮದಿಂದ ದೂರವಿಡಿರುವುದರಿಂದ ನನ್ನ ಪಾಪಗಳಿಂದ ನನ್ನನ್ನು ದೂರವಿಡಿಸು. ಓ ಅಲ್ಲಾಹನೇ, ಬಿಳಿ ಉಡುಪಿನಲ್ಲಿ ಕೊಳಕು ಶುದ್ಧವಾಗುವಂತೆ ನನ್ನನ್ನು ಪಾಪಗಳಿಂದ ಶುದ್ಧಮಾಡಿಸು. ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನ ಪಾಪಗಳನ್ನು ನೀರು, ಹಿಮ ಮತ್ತು ಆಲಿಕಲ್ಲುಗಳಿಂದ ತೊಳೆದುಕೊಳ್ಳು.", "ಆರಂಭಿಕ ತಕ್ಬೀರ್ ನಂತರ (ಸನಾ ಬದಲಿಗೆ ಕೂಡ ಹೇಳಬಹುದು).", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಇದನ್ನು ತಕ್ಬೀರ್ ಮತ್ತು ಪಠಣಗಳ ನಡುವೆ ಪಠಿಸಿದರು."),
        "dua_hamdan_kathiran" to DuaText("ರುಕುವಿನ ನಂತರ ಅಪಾರವಾದ ಪ್ರಶಂಸೆ", "ನಮ್ಮ ಒಡೆಯನೇ, ನಿನಗೆ ಸ್ತುತಿಯು-ಸಮೃದ್ಧವಾದ, ಶುದ್ಧವಾದ ಮತ್ತು ಆಶೀರ್ವಾದಿತವಾದ ಸ್ತುತಿಯು-ಸೇರಿದ್ದು.", "ರುಕುವಿನಿಂದ ಎದ್ದ ನಂತರ,'ರಬ್ಬಾನಾ ಲಾಕಲ್-ಹಮ್ದ್'ನೊಂದಿಗೆ.", "ಮೂವತ್ತಕ್ಕೂ ಹೆಚ್ಚು ದೇವತೆಗಳು ಇದನ್ನು ದಾಖಲಿಸಿದ ಮೊದಲ ವ್ಯಕ್ತಿಯಾಗಲು ಸ್ಪರ್ಧಿಸುತ್ತಿದ್ದರು."),
    )
}
